package tv.vela.launcher;
import org.json.*;
import java.util.*;
public final class JellyfinFeedTest {
    static int count;
    static void check(boolean ok,String why){count++;if(!ok)throw new AssertionError(why);}
    static String item="0123456789abcdef0123456789abcdef",series="abcdef0123456789abcdef0123456789";
    static JSONObject movie()throws Exception{return new JSONObject().put("Id",item).put("Name","Película de prueba").put("Type","Movie").put("RunTimeTicks",108_000_000_000L).put("DateCreated","2026-10-20T12:30:00.1234567Z").put("ImageTags",new JSONObject().put("Primary","poster").put("Logo","logo")).put("BackdropImageTags",new JSONArray().put("backdrop")).put("UserData",new JSONObject().put("PlaybackPositionTicks",27_000_000_000L).put("LastPlayedDate","2026-10-21T10:00:00Z").put("Played",false));}
    public static void main(String[] args)throws Exception{
        PlexClient.Film movie=JellyfinClient.parseFilm(movie(),true,false);check(movie!=null&&movie.provider.equals("Jellyfin")&&movie.packageName.equals(JellyfinClient.PACKAGE),"Source identity lost");check(movie.durationMs==10_800_000&&movie.positionMs==2_700_000&&movie.remainingMs()==8_100_000,"100ns ticks not converted to exact milliseconds");check(Math.abs(movie.progress-.25)<.001,"Progress mapping failed");check(movie.thumb.startsWith("/Items/"+item+"/Images/Primary?tag=")&&movie.art.contains("Backdrop")&&movie.logo.contains("Logo"),"Original image references lost");check(movie.addedAtMs>0&&movie.lastPlayedMs>movie.addedAtMs,"ISO timestamps, including tick precision, lost");
        JSONObject episode=movie().put("Type","Episode").put("SeriesName","Serie de prueba").put("SeriesId",series).put("SeriesPrimaryImageTag","seriesposter").put("ParentIndexNumber",2).put("IndexNumber",3);PlexClient.Film ep=JellyfinClient.parseFilm(episode,true,false);check(ep.key.equals(item)&&ep.title.equals("Serie de prueba")&&ep.thumb.contains(series)&&ep.episodeLabel.equals("T2 · E3"),"Episode lost playable ID, series artwork or season/episode");
        episode.remove("BackdropImageTags");episode.put("ParentBackdropItemId",series).put("ParentBackdropImageTags",new JSONArray().put("seriesbackdrop"));check(JellyfinClient.parseFilm(episode,true,false).art.contains(series),"Parent backdrop ignored");
        JSONObject season=movie().put("Type","Season").put("SeriesId",series).put("SeriesName","Serie nueva").put("SeriesPrimaryImageTag","seriesposter");PlexClient.Film recent=JellyfinClient.parseFilm(season,false,true);check(recent.key.equals(series)&&recent.title.equals("Serie nueva")&&recent.recentlyAdded&&recent.type.equals("show"),"Latest season was not represented by its series poster");check(JellyfinClient.parseFilm(season,true,false)==null,"Season offered for resume");
        JSONObject complete=movie();complete.getJSONObject("UserData").put("PlaybackPositionTicks",108_000_000_000L);check(JellyfinClient.parseFilm(complete,true,false)==null,"Finished playback offered");complete=movie();complete.getJSONObject("UserData").put("Played",true);check(JellyfinClient.parseFilm(complete,true,false)==null,"Played item offered");
        JSONObject missing=movie();missing.remove("UserData");PlexClient.Film unknown=JellyfinClient.parseFilm(missing,false,true);check(unknown.positionMs==-1&&unknown.remainingMs()==-1,"Missing offset invented");check(JellyfinClient.parseFilm(missing,true,false)==null,"Unstarted item offered for resume");
        check(JellyfinClient.parseFilm(movie().put("Id","../bad"),false,true)==null,"Invalid item ID accepted");check(JellyfinClient.parseFilm(movie().put("Type","Audio"),false,true)==null,"Audio displayed as a movie");check(JellyfinClient.imagePath(item,"Primary","../../bad").isEmpty(),"Image tag traversal accepted");
        List<PlexClient.Film> list=JellyfinClient.parse(new JSONArray().put(movie()).put(movie()),false,true,12);check(list.size()==1,"Duplicate media not removed within a shelf");JSONArray many=new JSONArray();for(int i=0;i<25;i++)many.put(movie());boolean refused=false;try{JellyfinClient.parse(many,false,true,12);}catch(Exception expected){refused=true;}check(refused,"Unbounded feed accepted");
        JSONArray folders=new JSONArray().put(new JSONObject().put("Id",item).put("Name","Cine").put("CollectionType","movies")).put(new JSONObject().put("Id",series).put("Name","Series").put("CollectionType","tvshows")).put(new JSONObject().put("Id","bad").put("CollectionType","movies"));List<PlexClient.Section> sections=JellyfinClient.parseSections(new JSONObject().put("Items",folders));check(sections.size()==2&&sections.get(0).type.equals("movie")&&sections.get(1).type.equals("show"),"Library types or UUID validation failed");
        check(JellyfinClient.guid(item).equals("01234567-89ab-cdef-0123-456789abcdef"),"Official Android TV item extra needs a UUID");check(JellyfinClient.id(JellyfinClient.guid(item)).equals(item),"Guid normalization failed");check(JellyfinClient.normalizeBase("https://example.org/jellyfin/").equals("https://example.org/jellyfin"),"Reverse proxy base path lost");
        for(String bad:new String[]{"file:///server","https://user:password@example.org","https://example.org?token=secret","https://example.org/#fragment","https://example.org/a/../b","https://example.org/%2e%2e/b","https://example.org:0"}){refused=false;try{JellyfinClient.normalizeBase(bad);}catch(Exception expected){refused=true;}check(refused,"Unsafe server address accepted");}
        JellyfinClient.validateAddress("http://127.0.0.1:18096/jellyfin");refused=false;try{JellyfinClient.validateAddress("http://8.8.8.8:8096");}catch(Exception expected){refused=true;}check(refused,"Public plaintext server accepted");
        JSONObject pending=new JSONObject(episode.toString()).put("Id","11111111111111111111111111111111");pending.getJSONObject("UserData").put("PlaybackPositionTicks",0);List<PlexClient.Film> next=JellyfinClient.withNextEpisodes(Collections.emptyList(),new JSONObject().put("Items",new JSONArray().put(pending).put(pending)));check(next.size()==1&&next.get(0).nextEpisode&&next.get(0).continuing&&next.get(0).positionMs==0&&next.get(0).remainingMs()>0,"Next Up item/progress/dedup failed");check(JellyfinClient.withNextEpisodes(Collections.singletonList(ep),new JSONObject().put("Items",new JSONArray().put(pending))).size()==1,"Next Up displaced a started episode of the same series");pending.getJSONObject("UserData").put("Played",true);check(JellyfinClient.withNextEpisodes(Collections.emptyList(),new JSONObject().put("Items",new JSONArray().put(pending))).isEmpty(),"played next episode accepted");check(JellyfinClient.watchedPath(item,series).equals("/UserPlayedItems/"+item+"?userId="+series),"watched item scope lost");refused=false;try{JellyfinClient.watchedPath("../bad",series);}catch(Exception expected){refused=true;}check(refused,"unsafe watched item accepted");
        System.out.println("PASS "+count+" Jellyfin metadata, progress, images, library, limits and URL checks");
    }
}
